\path (0,1.8) node[above,text=black,font=\fontsize{10}{12}\selectfont] {$f'(x)$};
\draw[thick,<->,draw=derivativeBlue,domain=-2.3:2.3,samples=70] plot (\x,{0.5*(3-\x*\x)});
